local TweenService = game:GetService("TweenService")

local intween = TweenInfo.new(.5, Enum.EasingStyle.Back, Enum.EasingDirection.Out)
local outtween = TweenInfo.new(.5, Enum.EasingStyle.Linear, Enum.EasingDirection.InOut, 0, false, 3)
local outInsttween = TweenInfo.new(.5, Enum.EasingStyle.Linear, Enum.EasingDirection.InOut)

local module = {}
module._content = nil
module._queue = {}
module._showing = {}

function module:SetContent(content)
    self._content = content
    self._listLayout = content:FindFirstChildWhichIsA("UIListLayout")
    self._content.ChildAdded:Connect(function(child)
        local count = #self._content:GetChildren() - 1
        if count > 5 then
            self._listLayout.VerticalAlignment = Enum.VerticalAlignment.Bottom;
        else
            self._listLayout.VerticalAlignment = Enum.VerticalAlignment.Top;
        end
    end)
end


function module:GetShowingCount()
    if #self._showing >= 5 then
        local first = table.remove(self._showing, 1)
        first["In"]:Cancel()
        first["Out"]:Cancel()
        if first["Context"] and first["Context"].Parent then
            local uiscale = first["Context"]:FindFirstChild("UIScale")
            local tweenOut = TweenService:Create(uiscale, outInsttween, {Scale = 0})
            tweenOut.Completed:Connect(function(playbackState)
                if playbackState == Enum.PlaybackState.Completed then
                    first["In"]:Destroy()
                    first["Out"]:Destroy()
                    first["Context"]:Destroy()
                    first = nil
                end
            end)
            tweenOut:Play()
        end
    end
    return true
end

function module:Add(content)
    table.insert(self._queue, content)
    if not self._running then
        self._running = true
        self:Update()
    end
end
    
function module:Show(context)
    context.Parent = self._content
    local uiscale = Instance.new("UIScale", context)
    uiscale.Scale = 0
    local tweenIn = TweenService:Create(uiscale, intween, {Scale = 1})
    local tweenOut = TweenService:Create(uiscale, outtween, {Scale = 0})

    table.insert(self._showing, {
        Context = context,
        In = tweenIn,
        Out = tweenOut
    })

    tweenIn.Completed:Connect(function(playbackState)
        if playbackState == Enum.PlaybackState.Completed and context and context.Parent then
            tweenOut:Play()
        end
    end)
    tweenOut.Completed:Connect(function(playbackState)
        if playbackState == Enum.PlaybackState.Completed then
            for i, v in pairs(self._showing) do
                if v.Context == context then
                    table.remove(self._showing, i)
                end
            end
            context:Destroy()
        end
    end)
    tweenIn:Play()
end

function module:Update()
    coroutine.wrap(function()
        if self:GetShowingCount() then
            local context = table.remove(self._queue, 1)
            if context then
                self:Show(context)
            end
            if self._queue[1] then
                wait()
                return self:Update()
            end
        end
        self._running = false
    end)()
end

return module